import React, { useState, useEffect } from 'react';

const COLORS = {
  bg: '#050505',
  card: '#111111',
  accent: '#3b82f6',
  gold: '#fbbf24',
  text: '#ffffff',
  muted: '#94a3b8',
  border: '#1e293b',
  success: '#10b981'
};

export default function App() {
  const [tab, setTab] = useState('dashboard');
  const [processos, setProcessos] = useState(() => {
    const salvo = localStorage.getItem('juris_v2_data');
    return salvo ? JSON.parse(salvo) : [];
  });

  // Estado para os cálculos trabalhistas
  const [trabalhista, setTrabalhista] = useState({ salario: '', meses: '', resultado: 0 });

  useEffect(() => {
    localStorage.setItem('juris_v2_data', JSON.stringify(processos));
  }, [processos]);

  // Função de Cálculo de Rescisão (Simplificada para o MVP)
  const calcularRescisao = () => {
    const decimo = (Number(trabalhista.salario) / 12) * Number(trabalhista.meses);
    const ferias = decimo + (decimo / 3);
    setTrabalhista({ ...trabalhista, resultado: decimo + ferias });
  };

  return (
    <div style={s.app}>
      {/* SIDEBAR */}
      <aside style={s.sidebar}>
        <div style={s.brand}>
          <div style={s.brandIcon}>J</div>
          <span>JurisPRO</span>
        </div>
        
        <nav style={s.nav}>
          <div style={s.navLink(tab === 'dashboard')} onClick={() => setTab('dashboard')}>📊 Dashboard</div>
          <div style={s.navLink(tab === 'calculos')} onClick={() => setTab('calculos')}>🧮 Calculadoras</div>
          <div style={s.navLink(tab === 'processos')} onClick={() => setTab('processos')}>📂 Processos</div>
          <div style={s.navLink(tab === 'financeiro')} onClick={() => setTab('financeiro')}>💰 Financeiro</div>
        </nav>

        <div style={s.userProfile}>
          <div style={s.avatar}>DR</div>
          <div>
            <div style={{fontSize: '14px', fontWeight: '600'}}>Dr. Rodrigo</div>
            <div style={{fontSize: '11px', color: COLORS.muted}}>Licença Premium</div>
          </div>
        </div>
      </aside>

      {/* CONTEÚDO */}
      <main style={s.content}>
        <header style={s.header}>
          <h2 style={{margin: 0}}>{tab.toUpperCase()}</h2>
          <div style={s.dateBadge}>quinta-feira, 14 de maio de 2026</div>
        </header>

        {/* ABA DASHBOARD */}
        {tab === 'dashboard' && (
          <div style={s.dashboardGrid}>
            <div style={s.statCard}>
              <span style={{color: COLORS.muted}}>Faturamento Bruto</span>
              <div style={{fontSize: '28px', fontWeight: 'bold', color: COLORS.success, margin: '10px 0'}}>
                R$ {processos.reduce((a, b) => a + (Number(b.valor) || 0), 0).toLocaleString()}
              </div>
            </div>
            <div style={s.statCard}>
              <span style={{color: COLORS.muted}}>Processos em Andamento</span>
              <div style={{fontSize: '28px', fontWeight: 'bold', color: COLORS.accent, margin: '10px 0'}}>{processos.length}</div>
            </div>
            <div style={{...s.card, gridColumn: 'span 2', height: '200px'}}>
              <h4 style={{marginTop: 0}}>Atividade do Escritório</h4>
              <div style={s.chartSim}>
                {[30, 80, 45, 90, 10, 60, 40].map((h, i) => <div key={i} style={{...s.bar, height: `${h}%`}} />)}
              </div>
            </div>
          </div>
        )}

        {/* ABA CALCULADORAS (O coração do produto) */}
        {tab === 'calculos' && (
          <div style={{display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px'}}>
            <div style={s.card}>
              <h3 style={{color: COLORS.gold}}>👷 Rescisão Trabalhista</h3>
              <p style={{fontSize: '13px', color: COLORS.muted}}>Cálculo de verbas rescisórias (Art. 477 CLT)</p>
              <input style={s.input} placeholder="Salário Base (R$)" type="number" onChange={e => setTrabalhista({...trabalhista, salario: e.target.value})} />
              <input style={s.input} placeholder="Meses de Contrato" type="number" onChange={e => setTrabalhista({...trabalhista, meses: e.target.value})} />
              <button style={s.btnAction} onClick={calcularRescisao}>CALCULAR AGORA</button>
              
              {trabalhista.resultado > 0 && (
                <div style={s.resultBox}>
                  Valor Estimado: <br/>
                  <strong style={{fontSize: '24px'}}>R$ {trabalhista.resultado.toLocaleString('pt-BR', {minimumFractionDigits: 2})}</strong>
                </div>
              )}
            </div>
            
            <div style={s.card}>
              <h3 style={{color: COLORS.accent}}>⚖️ Honorários Sucumbenciais</h3>
              <p style={{fontSize: '13px', color: COLORS.muted}}>Cálculo de 10% a 20% sobre a condenação.</p>
              {/* Adicionar campos similares aqui */}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

// ESTILOS
const s = {
  app: { display: 'flex', minHeight: '100vh', backgroundColor: COLORS.bg, color: COLORS.text, fontFamily: "'Inter', sans-serif" },
  sidebar: { width: '260px', backgroundColor: COLORS.card, borderRight: `1px solid ${COLORS.border}`, display: 'flex', flexDirection: 'column', padding: '20px' },
  brand: { display: 'flex', alignItems: 'center', gap: '12px', fontSize: '20px', fontWeight: 'bold', color: COLORS.accent, marginBottom: '40px' },
  brandIcon: { width: '35px', height: '35px', backgroundColor: COLORS.accent, color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: '8px' },
  nav: { flex: 1 },
  navLink: (active) => ({
    padding: '12px 15px', borderRadius: '10px', cursor: 'pointer', marginBottom: '8px',
    backgroundColor: active ? 'rgba(59, 130, 246, 0.1)' : 'transparent',
    color: active ? COLORS.accent : COLORS.muted,
    transition: '0.2s'
  }),
  userProfile: { display: 'flex', alignItems: 'center', gap: '12px', padding: '15px', borderTop: `1px solid ${COLORS.border}` },
  avatar: { width: '40px', height: '40px', borderRadius: '50%', backgroundColor: '#333', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '12px', fontWeight: 'bold' },
  content: { flex: 1, padding: '40px', overflowY: 'auto' },
  header: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '40px' },
  dateBadge: { padding: '8px 16px', backgroundColor: COLORS.card, borderRadius: '20px', fontSize: '12px', color: COLORS.muted },
  dashboardGrid: { display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px' },
